create table hf_transactions (
    transaction_id number generated by default on null as identity (start with 100) constraint hf_transactions_pk primary key,
    transaction_date date default trunc(sysdate) not null,
    description varchar2(200 char) not null,
    category varchar2(30 char) not null,
    amount number(14,2) not null,
    constraint hf_transactions_description_ck check (trim(description) is not null),
    constraint hf_transactions_amount_ck check (amount <> 0),
    constraint hf_transactions_category_ck check (category in ('Income','Housing','Food','Utilities','Transport','Leisure','Insurance','Health','Other'))
);

insert into hf_transactions (transaction_id, transaction_date, description, category, amount)
select 1 transaction_id, trunc(sysdate,'MM') + 0 transaction_date, 'Salary' description, 'Income' category, 4200 amount from dual union all select 2 transaction_id, trunc(sysdate,'MM') + 1 transaction_date, 'Freelance' description, 'Income' category, 650 amount from dual union all select 3 transaction_id, trunc(sysdate,'MM') + 2 transaction_date, 'Rent' description, 'Housing' category, -1450 amount from dual union all select 4 transaction_id, trunc(sysdate,'MM') + 3 transaction_date, 'Groceries' description, 'Food' category, -380 amount from dual union all select 5 transaction_id, trunc(sysdate,'MM') + 4 transaction_date, 'Electricity' description, 'Utilities' category, -95 amount from dual union all select 6 transaction_id, trunc(sysdate,'MM') + 5 transaction_date, 'Internet' description, 'Utilities' category, -45 amount from dual union all select 7 transaction_id, trunc(sysdate,'MM') + 6 transaction_date, 'Train pass' description, 'Transport' category, -65 amount from dual union all select 8 transaction_id, trunc(sysdate,'MM') + 7 transaction_date, 'Dining out' description, 'Leisure' category, -120 amount from dual union all select 9 transaction_id, trunc(sysdate,'MM') + 8 transaction_date, 'Streaming' description, 'Leisure' category, -25 amount from dual union all select 10 transaction_id, trunc(sysdate,'MM') + 9 transaction_date, 'Insurance' description, 'Insurance' category, -110 amount from dual;

commit;
